INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('28/02/2011', 'Ponto Facultativo - Memória de Zé Paraná', 'FACULTATIVO', 'Ponto facultativo instituído em memória ao falecimento do Comendador José Pedro Dias, popularmente conhecido como Zé Paraná, colonizador e fundador do município de Juara, conforme previsto na Lei Municipal nº 1.543/2004.', 'MT', '5105101');
