INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('21/04/2011', 'Dia de Tiradentes', 'FACULTATIVO', 'Feriado nacional estabelecido pela Lei nº 662/1949 e ratificado pela Lei nº 10.607/2002. Presta homenagem a Joaquim José da Silva Xavier, o Tiradentes, mártir da Inconfidência Mineira e patrono cívico da nação brasileira, executado nesta data em 1792 por sua luta pela independência do Brasil.', null, null);
INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('23/06/2011', 'Corpus Christi', 'FACULTATIVO', 'Ponto Facultativo no País, mas Feriado Municipal em algumas cidades.. Corpus Christi, expressão latina que significa Corpo de Cristo, é uma festa Cristã realizada na quinta-feira seguinte ao domingo da Santíssima Trindade.', null, null);
