INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('15/10/2011', 'Dia do Professor', 'FACULTATIVO', 'FERIADO ESCOLAR - No dia 15 de outubro de 1827 (dia consagrado à educadora Santa Teresa de Ávila), o Imperador do Brasil, Pedro I, baixou um Decreto Imperial que criou o Ensino Elementar no Brasil. Pelo decreto, "todas as cidades, vilas e lugarejos teriam suas escolas de primeiras letras"', null, null);
