INSERT INTO feriado (data, nome, tipo, descricao, uf, codigo_ibge) VALUES ('18/11/2011', 'Tratado de Petrópolis', 'FACULTATIVO', 'Feriado no dia 17de Novembro, segundo a lei Nº 57/1965, mas adiado para próxima Sexta-Feira. O atual estado brasileiro do Acre era, no início do século XX, uma região pertencente à Bolívia e foi incorporado ao Brasil pelo Barão do Rio Branco através do Tratado de Petrópolis, firmado em 17 de novembro de 1903.', null, null);
